package com.exelynt.booking.repository; import com.exelynt.booking.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDateTime; public interface ReservationRepository extends JpaRepository<Reservation,Long>,JpaSpecificationExecutor<Reservation>{@Query("select count(r)>0 from Reservation r where r.resource.id=:resourceId and r.status in :statuses and r.startTime < :endTime and r.endTime > :startTime and (:excludeId is null or r.id <> :excludeId)") boolean hasConflict(@Param("resourceId") Long resourceId,@Param("startTime") LocalDateTime start,@Param("endTime") LocalDateTime end,@Param("statuses") java.util.Collection<ReservationStatus> statuses,@Param("excludeId") Long excludeId);}
